from collections import deque

def bfs(n, s):
    N=n+2
    start=tuple(list(s)+['.','.'])
    # blank positions: find first '.'? assume adjacent
    # moves: find e = index of first '.' (0-based), must have e+1 '.'.
    # for each i where board[i]!='.' and board[i+1]!='.', and i != e (can't pick overlapping? Actually i,i+1 must be occupied, e,e+1 empty, so they don't overlap. If board has only 2 empties adjacent, any i with occupied pair automatically disjoint from e? Could overlap partially? E.g., board [B,.,.,B...] blanks at 2,3 (1-indexed 2,3). Occupied pairs: maybe (1,2) includes blank, not allowed. So must check both occupied. So disjoint automatically except maybe? If blanks adjacent, any occupied pair cannot overlap blanks because blanks are '.'.
    # So generate next by swapping pairs.
    dist={start:0}
    q=deque([start])
    while q:
        cur=q.popleft()
        d=dist[cur]
        # find e
        # assume blanks adjacent; find e
        e=None
        for idx in range(N-1):
            if cur[idx]=='.' and cur[idx+1]=='.':
                e=idx
                break
        if e is None:
            print("nonadjacent blanks!",cur)
            # generalize: find positions of '.'; they may be nonadjacent if model allows? but in this model they stay adjacent
            continue
        for i in range(N-1):
            if i==e: continue
            if cur[i]=='.' or cur[i+1]=='.':
                continue
            # move i,i+1 to e,e+1
            lst=list(cur)
            # swap?
            # new board: positions i,i+1 become '.', e,e+1 become old i,i+1
            a,b=lst[i],lst[i+1]
            lst[e],lst[e+1]=a,b
            lst[i],lst[i+1]='.','.'
            nxt=tuple(lst)
            if nxt not in dist:
                dist[nxt]=d+1
                q.append(nxt)
    return dist

def min_dist(n,s,t, mode='exact_end'):
    dist=bfs(n,s)
    # mode exact_end: board == tuple(t+ '..')
    # mode first_n: first n cells == t (implies blanks at end, same as exact_end? Actually if first n == t, blanks must be at n+1,n+2 because only 2 blanks total and t has no blanks. So same.)
    # mode order: sequence ignoring '.' == t? but t as sequence with duplicates, need to match counts? Actually ignoring blanks, order of stones left-to-right equals t string. That condition.
    best=None
    for state,d in dist.items():
        if mode=='exact_end':
            if ''.join(state)==t+'..':
                if best is None or d<best:
                    best=d
        elif mode=='order':
            seq=''.join(c for c in state if c!='.')
            if seq==t:
                if best is None or d<best:
                    best=d
        elif mode=='first_n_ignore_blanks_pos?':
            pass
    return best, len(dist)

