def count_states(n,s):
    N=n+2
    start=tuple(list(s)+['.','.'])
    dist={start:0}
    q=deque([start])
    while q:
        cur=q.popleft()
        # find e
        e=None
        for idx in range(N-1):
            if cur[idx]=='.' and cur[idx+1]=='.':
                e=idx
                break
        if e is None:
            continue
        for i in range(N-1):
            if i==e: continue
            if cur[i]=='.' or cur[i+1]=='.':
                continue
            lst=list(cur)
            a,b=lst[i],lst[i+1]
            lst[e],lst[e+1]=a,b
            lst[i],lst[i+1]='.','.'
            nxt=tuple(lst)
            if nxt not in dist:
                dist[nxt]=0
                q.append(nxt)
