from collections import deque
import time

def neighbors_of(state, N):
    # state is str
    e = state.find('..')  # since blanks adjacent, should find
    # if not found (should not happen), fallback to find '.' positions? but assume found
    if e==-1:
        # fallback: find all '.'? shouldn't happen
        return
        yield
    for i in range(N-1):
        if i==e:
            continue
        if state[i]=='.' or state[i+1]=='.':
            continue
        # swap
        lst = list(state)
        a,b = lst[i], lst[i+1]
        lst[e], lst[e+1]=a,b
        lst[i], lst[i+1]='.','.'
        yield ''.join(lst)

def bidir(n,s,t):
    N=n+2
    start=s+'..'
    target=t+'..'
    if start==target:
        return 0
    from collections import deque
    dist_f={start:0}
    dist_b={target:0}
    qf=deque([start])
    qb=deque([target])
    while qf and qb:
        # expand smaller frontier level
        if len(qf) <= len(qb):
            for _ in range(len(qf)):
                cur=qf.popleft()
                d=dist_f[cur]
                for nb in neighbors_of(cur,N):
                    if nb in dist_f:
                        continue
                    if nb in dist_b:
                        return d+1+dist_b[nb]
                    dist_f[nb]=d+1
                    qf.append(nb)
        else:
            for _ in range(len(qb)):
                cur=qb.popleft()
                d=dist_b[cur]
                for nb in neighbors_of(cur,N):
                    if nb in dist_b:
                        continue
                    if nb in dist_f:
                        return d+1+dist_f[nb]
                    dist_b[nb]=d+1
                    qb.append(nb)
    return None

